1	// Setup identity: harness + model + rules hash, plus ground truth from the prompt tag.
2	// See docs/DESIGN.md §"Setups" and §"Recovering the model and the rules file from transcripts".
3	import { createHash } from "node:crypto";
4	
5	/**
6	 * The session fields identity needs. `ParsedSession` from src/ingest/parse.ts satisfies it.
7	 * `rules_hash` is the transcript-derived hash (Claude `instructions` attachments, Codex `agents_md`),
8	 * or null when the transcript records no rules file.
9	 */
10	export interface IdentitySource {
11	  /** Agent display name as Entire records it, e.g. "Claude Code" or "Codex". */
12	  harness: string;
13	  /** Resolved model, or "unknown" when neither metadata nor transcript records it. */
14	  model: string;
15	  rules_hash: string | null;
16	  /** The commit that carries this session's checkpoint trailer, or null. */
17	  commit_sha: string | null;
18	  first_prompt: string;
19	}
20	
21	/** Ground truth written by the self-build protocol: `[roster setup=<id> task=<Txx>]`. */
22	export interface SetupTag {
23	  setup: string;
24	  task: string;
25	}
26	
27	export interface Identity {
28	  /** Short hash of (harness, model, rulesHash); null when the rules are unknown. */
29	  setupId: string | null;
30	  /** Normalised harness id, e.g. "claude-code", "codex". */
31	  harness: string;
32	  model: string;
33	  rulesHash: string | null;
34	  rulesPath: string | null;
35	  tag: SetupTag | null;
36	}
37	
38	const TAG_RE = /^\s*\[roster setup=([^\s\]]+) task=([^\s\]]+)\]/;
39	
40	/** Rules files a repo can carry, matched against the files tracked at the parent commit, for any harness. */
41	const isRulesFile = (p: string) =>
42	  p === "CLAUDE.md" ||
43	  p === "AGENTS.md" ||
44	  p === ".cursorrules" ||
45	  p === ".github/copilot-instructions.md" ||
46	  p.startsWith(".cursor/rules/");
47	
48	/** Rules hash and path for a session whose parent commit carries no rules file: a real configuration. */
49	const NO_RULES_HASH = createHash("sha256").update("no-rules-file").digest("hex");
50	const NO_RULES_PATH = "(none)";
51	
52	/** Model used in the setup id when the session records none, so sessions still group by harness. */
53	const UNKNOWN_MODEL_ID = "unknown-model";
54	
55	/** Default rules path recorded when the transcript carries the rules text itself. */
56	const DEFAULT_RULES_PATH: Record<string, string> = {
57	  "claude-code": "CLAUDE.md",
58	  codex: "AGENTS.md",
59	};
60	
61	/** "Claude Code" → "claude-code", "Factory AI Droid" → "factory-ai-droid". */
62	export function harnessId(agent: string): string {
63	  return agent
64	    .toLowerCase()
65	    .replace(/[^a-z0-9]+/g, "-")
66	    .replace(/^-|-$/g, "");
67	}
68	
69	/** Normalised per DESIGN.md: LF line endings, trimmed. */
70	const normalise = (text: string) => text.replace(/\r\n?/g, "\n").trim();
71	const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
72	
73	interface RulesFile {
74	  path?: unknown;
75	  type?: unknown;
76	  content?: unknown;
77	}
78	
79	/**
80	 * Rules hash of a Claude Code transcript: every `instructions` / `nested_memory` file of type
81	 * Project or Local, deduplicated and sorted by repo-relative path (the session's recorded cwd,
82	 * or a `<repo>` placeholder, is stripped). User-level files and paths outside the repo are
83	 * excluded. Null when the transcript records no such file.
84	 */
85	export function claudeRulesHash(rows: ReadonlyArray<Record<string, any>>): string | null {
86	  const cwd = rows.find((r) => typeof r.cwd === "string" && r.cwd)?.cwd?.replace(/\/+$/, "") as string | undefined;
87	  const files = new Map<string, string>();
88	  for (const r of rows) {
89	    const a = r.type === "attachment" ? r.attachment : null;
90	    if (!a || (a.type !== "instructions" && a.type !== "nested_memory")) continue;
91	    const list: RulesFile[] = Array.isArray(a.files) ? a.files : [a];
92	    for (const f of list) {
93	      if ((f.type !== "Project" && f.type !== "Local") || typeof f.path !== "string" || typeof f.content !== "string") continue;
94	      let rel = f.path;
95	      if (rel.startsWith("<repo>/")) rel = rel.slice(7);
96	      else if (cwd && rel.startsWith(cwd + "/")) rel = rel.slice(cwd.length + 1);
97	      else if (rel.startsWith("/") || rel.startsWith("~")) continue; // outside the repo/worktree
98	      files.set(rel, normalise(f.content));
99	    }
100	  }
101	  if (files.size === 0) return null;
102	  const texts = [...files.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([, t]) => t);
103	  return sha256(texts.join("\n"));
104	}
105	
106	/** Short setup id, or null when the rules hash is unknown (never a guess). */
107	export function setupIdOf(harness: string, model: string, rulesHash: string | null): string | null {
108	  if (rulesHash === null) return null;
109	  return sha256([harness, model, rulesHash].join("\n")).slice(0, 12);
110	}
111	
112	/** Parses `[roster setup=X task=Txx]` at the start of the first prompt. */
113	export function parseTag(firstPrompt: string): SetupTag | null {
114	  const m = TAG_RE.exec(firstPrompt);
115	  return m ? { setup: m[1]!, task: m[2]! } : null;
116	}
117	
118	function git(repo: string, args: string[]): string | null {
119	  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
120	  return p.exitCode === 0 ? p.stdout.toString() : null;
121	}
122	
123	/**
124	 * Rules in effect at a commit's parent: the rules files as they stood before the session's first
125	 * linked commit. A parent with no rules file yields the no-rules sentinel. Null when the commit,
126	 * its parent (a root commit has none), or the git read is unknown.
127	 */
128	function rulesAtParent(harness: string, repo: string, commitSha: string | null): { rulesHash: string; rulesPath: string } | null {
129	  if (!commitSha) return null;
130	  const parent = git(repo, ["rev-parse", "--verify", "-q", `${commitSha}^`])?.trim();
131	  if (!parent) return null;
132	  const tracked = git(repo, ["ls-tree", "-r", "--name-only", parent])?.split("\n").filter(Boolean);
133	  if (!tracked) return null;
134	  // The harness's own rules file when the parent has it; otherwise every rules file the repo carries.
135	  const primary = DEFAULT_RULES_PATH[harness];
136	  const paths = (primary && tracked.includes(primary) ? [primary] : tracked.filter(isRulesFile)).sort();
137	  if (paths.length === 0) return { rulesHash: NO_RULES_HASH, rulesPath: NO_RULES_PATH };
138	  const texts: string[] = [];
139	  for (const p of paths) {
140	    const text = git(repo, ["show", `${parent}:${p}`]);
141	    if (text === null) return null;
142	    texts.push(normalise(text));
143	  }
144	  return { rulesHash: sha256(texts.join("\n")), rulesPath: paths.join(",") };
145	}
146	
147	/**
148	 * Setup of one session. The rules hash comes from the transcript when it records one, otherwise
149	 * from the rules files at the parent of the session's commit (or the no-rules sentinel when that
150	 * parent has none). Null only when neither source is available.
151	 */
152	export function identify(session: IdentitySource, repoPath: string): Identity {
153	  const harness = harnessId(session.harness);
154	  const model = session.model || "unknown";
155	  let rulesHash = session.rules_hash;
156	  let rulesPath: string | null = null;
157	  if (rulesHash !== null) {
158	    rulesPath = DEFAULT_RULES_PATH[harness] ?? null;
159	  } else {
160	    const found = rulesAtParent(harness, repoPath, session.commit_sha);
161	    if (found) ({ rulesHash, rulesPath } = found);
162	  }
163	  return {
164	    setupId: setupIdOf(harness, session.model || UNKNOWN_MODEL_ID, rulesHash),
165	    harness,
166	    model,
167	    rulesHash,
168	    rulesPath,
169	    tag: parseTag(session.first_prompt),
170	  };
171	}
172	
173	/**
174	 * Share of tagged sessions whose inferred setup maps 1:1 to its tag. Each inferred setup id is
175	 * matched to the tag it most often carries, and each tag to the id it most often gets; a session
176	 * counts when both majorities agree with it. Untagged sessions are excluded. Null when nothing is tagged.
177	 */
178	export function inferenceAccuracy(sessions: ReadonlyArray<Pick<Identity, "setupId" | "tag">>): number | null {
179	  const tagged = sessions.filter((s): s is { setupId: string | null; tag: SetupTag } => s.tag !== null);
180	  if (tagged.length === 0) return null;
181	  const tagsById = new Map<string, Map<string, number>>();
182	  const idsByTag = new Map<string, Map<string, number>>();
183	  const bump = (outer: Map<string, Map<string, number>>, k: string, inner: string) => {
184	    const m = outer.get(k) ?? new Map<string, number>();
185	    m.set(inner, (m.get(inner) ?? 0) + 1);
186	    outer.set(k, m);
187	  };
188	  for (const s of tagged) {
189	    if (s.setupId === null) continue;
190	    bump(tagsById, s.setupId, s.tag.setup);
191	    bump(idsByTag, s.tag.setup, s.setupId);
192	  }
193	  // A tie means no single mapping, so it counts as no match.
194	  const majority = (m: Map<string, number> | undefined) => {
195	    let best: string | null = null;
196	    let n = 0;
197	    let tied = false;
198	    for (const [k, v] of m ?? []) {
199	      if (v > n) {
200	        best = k;
201	        n = v;
202	        tied = false;
203	      } else if (v === n) tied = true;
204	    }
205	    return tied ? null : best;
206	  };
207	  const ok = tagged.filter(
208	    (s) =>
209	      s.setupId !== null &&
210	      majority(tagsById.get(s.setupId)) === s.tag.setup &&
211	      majority(idsByTag.get(s.tag.setup)) === s.setupId,
212	  ).length;
213	  return ok / tagged.length;
214	}
